13	    "meta":  {
14	      "type": "object",
15	      "properties": {
16	        "score": {"type": "number", "min": 0, "max": 100}
17	      }
18	    }
19	  }
20	}
21	
22	Supported types: string, integer, number, boolean, array, object, null
23	Constraints:     required, enum, pattern, min, max, min_length, max_length, min_items, max_items
24	"""
25	
26	import json
27	import re
28	import sys
29	from pathlib import Path
